import cv2, glob, numpy as np

def count_matches(img, templ, threshold):
    res = cv2.matchTemplate(img, templ, cv2.TM_CCOEFF_NORMED)
    h, w = templ.shape[:2]
    count = 0
    while True:
        min_val, max_val, min_loc, max_loc = cv2.minMaxLoc(res)
        if max_val < threshold:
            break
        count += 1
        x, y = max_loc
        # suppress region around this match
        x0 = max(0, x - w//2)
        y0 = max(0, y - h//2)
        x1 = min(res.shape[1], x + w//2)
        y1 = min(res.shape[0], y + h//2)
        res[y0:y1, x0:x1] = -1
    return count

templates = {name: cv2.imread(f'/root/{name}.png', cv2.IMREAD_GRAYSCALE) for name in ['coin','enemy','turtle']}
frames = sorted(glob.glob('/root/keyframes_*.png'))

thresholds = {'coin':0.8, 'enemy':0.8, 'turtle':0.8}

for f in frames:
    img = cv2.imread(f, cv2.IMREAD_GRAYSCALE)
    counts = {}
    for name,templ in templates.items():
        counts[name] = count_matches(img, templ, thresholds[name])
    print(f, counts)
