def count_nms(img, templ, threshold, nms_threshold=0.3):
    res = cv2.matchTemplate(img, templ, cv2.TM_CCOEFF_NORMED)
    h, w = templ.shape[:2]
    ys, xs = np.where(res >= threshold)
