import cv2, glob, csv
import numpy as np

frames = sorted(glob.glob('/root/keyframes_*.png'))

templates = {
    'coins': cv2.imread('/root/coin.png', cv2.IMREAD_GRAYSCALE),
    'enemies': cv2.imread('/root/enemy.png', cv2.IMREAD_GRAYSCALE),
    'turtles': cv2.imread('/root/turtle.png', cv2.IMREAD_GRAYSCALE),
}

thresholds = {
    'coins': 0.8,
    'enemies': 0.9,
    'turtles': 0.9,
}

def count_clusters(res, w, h, threshold):
    ys, xs = np.where(res >= threshold)
    points = list(zip(xs, ys))
    clusters = []
    for x, y in points:
        placed = False
        for cx, cy in clusters:
            if abs(x - cx) <= w//2 and abs(y - cy) <= h//2:
                placed = True
                break
        if not placed:
            clusters.append((x, y))
    return len(clusters)

rows = []
for f in frames:
    img = cv2.imread(f, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise SystemExit(f'Failed to read {f}')
    counts = {}
    for key, templ in templates.items():
        if templ is None:
            raise SystemExit(f'Failed to read template for {key}')
        res = cv2.matchTemplate(img, templ, cv2.TM_CCOEFF_NORMED)
        h, w = templ.shape[:2]
        counts[key] = count_clusters(res, w, h, thresholds[key])
    rows.append([f, counts['coins'], counts['enemies'], counts['turtles']])

out_path = '/root/counting_results.csv'
with open(out_path, 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['frame_id', 'coins', 'enemies', 'turtles'])
    writer.writerows(rows)

print('wrote', out_path, 'rows', len(rows))
PY"}
